# ruff: noqa: E501
"""Markdown report for the SA2.2 / SA2.3 baselines (English prose, tables generated by code)."""

import datetime as dt
from dataclasses import dataclass

import numpy as np
import pandas as pd

from firecal.stages.grid.filters import FilterConfig
from firecal.stages.harmonize.evaluate import (
    INTERVALS,
    MAIN_PAIRS,
    METHODS,
    NOMINAL,
    PAIRS,
    FoldOut,
    coverage_by_size,
    coverage_table,
    score_table,
)
from firecal.stages.harmonize.intervals import MIN_PER_BIN, SMALL_MONTH, SMALL_YEAR
from firecal.stages.harmonize.ml import MLResult
from firecal.stages.harmonize.regions import Cube
from firecal.stages.harmonize.stability import step_summary

DIRECTION = {
    "viirs_to_modis": "VIIRS (S-NPP) -> MODIS-equivalent",
    "modis_to_viirs": "MODIS -> VIIRS-equivalent (inverse series)",
}
STEP_GROUPS = {
    "2012-2017": (2012, 2017),
    "2018": (2018, 2018),
    "2019-2022": (2019, 2022),
    "2023": (2023, 2023),
    "2024-2025": (2024, 2025),
}


@dataclass
class ReportInput:
    cube: Cube
    folds: dict[tuple[str, str], list[FoldOut]]  # (pair, scheme) -> folds
    factors: pd.DataFrame
    grid_tables: dict[str, pd.DataFrame]
    det_tables: dict[str, pd.DataFrame]
    cfg: FilterConfig
    run_date: dt.date
    ml: "MLResult | None" = None  # SA2.4 / SA2.7 (optional, `--ml`)
    ml_prev: "MLResult | None" = None  # earlier ML run, for the cap-shift comparison


def md_table(headers: list[str], rows: list[list]) -> list[str]:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return out


def pct(x: float, sign: bool = False) -> str:
    if x is None or not np.isfinite(x):
        return "-"
    return f"{x * 100:+.1f} %" if sign else f"{x * 100:.1f} %"


def num(x: float, nd: int = 3) -> str:
    return "-" if x is None or not np.isfinite(x) else f"{x:.{nd}f}"


def hhmm(h: float) -> str:
    if h is None or not np.isfinite(h):
        return "-"
    m = round((h % 24) * 60)
    return f"{m // 60 % 24:02d}:{m % 60:02d}"


def _row(scores: pd.DataFrame, pair, scheme, method, year, level) -> pd.Series | None:
    s = scores[
        (scores["pair"] == pair)
        & (scores["scheme"] == scheme)
        & (scores["method"] == method)
        & (scores["test_year"].astype(str) == str(year))
        & (scores["level"] == level)
    ]
    return s.iloc[0] if len(s) else None


def _lower(scores, pair, scheme, level="block-month", year="all") -> str:
    a, b = _row(scores, pair, scheme, "sf", year, level), _row(scores, pair, scheme, "qm", year, level)
    if a is None or b is None:
        return "-"
    return METHODS["sf"] if a["wape"] <= b["wape"] else METHODS["qm"]


def _all_folds(inp: ReportInput) -> list[FoldOut]:
    return [f for fs in inp.folds.values() for f in fs]


def build_report(inp: ReportInput) -> str:
    cube, cfg = inp.cube, inp.cfg
    folds = _all_folds(inp)
    scores = score_table(folds)
    cov = coverage_table(folds)
    snpp_first = cube.dates[cube.valid["snpp"]][0].strftime("%Y-%m")
    last = cube.dates[-1].strftime("%Y-%m")
    L: list[str] = ["# SA2.2 and SA2.3 MODIS-VIIRS harmonization baselines", ""]
    L += [
        f"Run: {inp.run_date.isoformat()}, with `firecal harmonize evaluate` (tables generated by code). "
        "Source: NASA FIRMS per-country files (Argentina), standard processing "
        "(MODIS, VIIRS S-NPP and NOAA-20; the detail of each processing version is unverified).",
        f"Period of the local data: 2000-11 to {last}; overlap period used: {snpp_first} to {last}.",
        f"Filters: type in {list(cfg.types)}, MODIS confidence >= {cfg.modis_min_confidence}, "
        f"VIIRS class in {list(cfg.viirs_classes)} (default `FilterConfig`). Count: detections after the "
        "filter, summed from the 0.1° grid.",
        "",
        "Everything is retrospective: it counts hot spots already detected and is not an alert system.",
        "",
    ]

    # --- Resumen ---
    L += ["## Summary", ""]
    nf = inp.factors.set_index("pair")
    L.append(
        f"- National factor (ratio of sums, in-sample, {snpp_first} to {last}): "
        f"VIIRS -> MODIS = {num(nf.loc['viirs_to_modis', 'factor'])} "
        f"(day {num(nf.loc['viirs_to_modis', 'factor_day'])}, night {num(nf.loc['viirs_to_modis', 'factor_night'])}); "
        f"MODIS -> VIIRS = {num(nf.loc['modis_to_viirs', 'factor'])} "
        f"(day {num(nf.loc['modis_to_viirs', 'factor_day'])}, night {num(nf.loc['modis_to_viirs', 'factor_night'])})."
    )
    for pair in MAIN_PAIRS:
        for scheme, name in (("loyo", "leave-one-year-out"), ("rolling", "rolling origin")):
            a = _row(scores, pair, scheme, "sf", "all", "block-month")
            b = _row(scores, pair, scheme, "qm", "all", "block-month")
            ay = _row(scores, pair, scheme, "sf", "all", "block-year")
            by = _row(scores, pair, scheme, "qm", "all", "block-year")
            if a is None or b is None:
                continue
            L.append(
                f"- {DIRECTION[pair]}, {name}: block-month WAPE SA2.2 {pct(a['wape'])} vs SA2.3 {pct(b['wape'])} "
                f"(lower error: {_lower(scores, pair, scheme)}); block-year WAPE SA2.2 {pct(ay['wape'])} vs "
                f"SA2.3 {pct(by['wape'])} (lower error: {_lower(scores, pair, scheme, 'block-year')}); "
                f"relative bias SA2.2 {pct(a['bias'], True)}, SA2.3 {pct(b['bias'], True)}."
            )
    for _, r in cov[(cov["scheme"] == "loyo") & (cov["test_year"].astype(str) == "all")].iterrows():
        if r["pair"] == "viirs_to_modis" and r["interval"] != "conformal":
            continue
        L.append(
            f"- {DIRECTION[r['pair']]}, empirical coverage of the {INTERVALS[r['interval']]} interval (nominal "
            f"{NOMINAL:.0%}, leave-one-year-out, {r['level']} with source > 0, all test years): "
            f"{pct(r['coverage'])}, relative width {num(r['rel_width'], 2)}; with source or observed > 0 "
            f"(earlier definition) {pct(r['coverage_any'])}."
        )
    mod = inp.grid_tables["modis_snpp"]
    steps = step_summary(mod, "ratio", STEP_GROUPS)
    L.append(
        "- National MODIS/S-NPP ratio by period (mean of the yearly ratios): "
        + ", ".join(f"{k} {num(v)}" for k, v in steps.items())
        + "."
    )
    types = inp.det_tables["types"]
    if not types.empty:
        ts = step_summary(types, "ratio_all", STEP_GROUPS)
        td = step_summary(types, "ratio_def", STEP_GROUPS)
        L.append(
            "- Same ratio without the `type` filter: "
            + ", ".join(f"{k} {num(v)}" for k, v in ts.items())
            + "; with the default filter from the detections: "
            + ", ".join(f"{k} {num(v)}" for k, v in td.items())
            + "."
        )
    L.append("")

    # --- Datos y supuestos ---
    L += ["## Data and assumptions", ""]
    L += [
        "- Scales: MODIS = Terra + Aqua; VIIRS = S-NPP only. NOAA-20 is not added to S-NPP: a transfer factor "
        "NOAA-20 -> S-NPP is fitted from 2018-05.",
        "- Regions: 2.5° blocks (origin -90/-180), "
        f"{len(cube.blocks)} blocks with at least one hot spot. Day and night are fitted separately and summed.",
        "- Partial months excluded: S-NPP 2012-01, NOAA-20 2018-04, Aqua 2002-07.",
        f"- First S-NPP month in the local data: {snpp_first}.",
        "- Unit: fitted on sums per block x month of the year x day/night; evaluated per block-month of each "
        "test year and per block-year total.",
        "- Leave-one-year-out: each year is the test year once; training excludes the test year and 6 months on each side. "
        "Rolling origin: train on all earlier years, evaluate the next one (no gap).",
        "- SA2.2: `f = (M + k * f_national) / (V + k)`; `k` is chosen inside the training set with an inner leave-one-year-out "
        "(6-month gap), minimizing the block-month WAPE, over the grid "
        "{0, 5, 20, 100, 500, 2000, 10000}.",
        "- SA2.3: per-block quantile mapping on block-month totals (months of the year pooled); positives only; "
        "zero maps to zero; above the training maximum, constant ratio; with fewer than 12 positive months "
        "in either series the block uses the mapping of all blocks pooled.",
        "- Metrics: relative bias = sum(pred)/sum(obs) - 1; WAPE = sum|pred-obs|/sum(obs); MAE; mean Poisson "
        "deviance (minimum predicted mean 0.001). They are block-month totals (n = blocks x test months) and "
        "block-year totals.",
        "",
    ]

    # --- Factores nacionales ---
    L += ["## National factors (in-sample)", ""]
    L += [
        "Ratio of target/source sums over all months of the pair, without validation (descriptive). "
        "`NOAA-20 -> S-NPP` is the transfer factor from 2018-05.",
        "",
    ]
    rows = [
        [
            PAIRS[r["pair"]].label,
            f"{r['from']} to {r['to']}",
            r["months"],
            num(r["factor"]),
            num(r["factor_day"]),
            num(r["factor_night"]),
        ]
        for _, r in inp.factors.iterrows()
    ]
    L += md_table(["Pair", "Months", "N", "Total", "Day", "Night"], rows)
    L += ["", "National factor by month of the year (day and night together):", ""]
    mcols = [f"m{m:02d}" for m in range(1, 13)]
    rows = [
        [PAIRS[r["pair"]].label] + [num(r[c]) for c in mcols]
        for _, r in inp.factors.iterrows()
        if r["pair"] in MAIN_PAIRS
    ]
    L += md_table(["Pair"] + [str(m) for m in range(1, 13)], rows)
    L.append("")

    # --- Errores ---
    L += ["## Error by method and direction (all test years pooled)", ""]
    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        rows = []
        for scheme, sname in (("loyo", "leave-one-year-out"), ("rolling", "rolling origin")):
            for method, mname in METHODS.items():
                a = _row(scores, pair, scheme, method, "all", "block-month")
                b = _row(scores, pair, scheme, method, "all", "block-year")
                if a is None:
                    continue
                rows.append(
                    [
                        sname,
                        mname,
                        pct(a["bias"], True),
                        pct(a["wape"]),
                        num(a["mae"], 1),
                        num(a["deviance"], 2),
                        pct(b["bias"], True),
                        pct(b["wape"]),
                        num(b["mae"], 1),
                    ]
                )
        L += md_table(
            [
                "Scheme",
                "Method",
                "Bias b-month",
                "WAPE b-month",
                "MAE b-month",
                "Deviance b-month",
                "Bias b-year",
                "WAPE b-year",
                "MAE b-year",
            ],
            rows,
        )
        L.append("")

    # --- By year ---
    L += ["## Error by test year (leave-one-year-out)", ""]
    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        years = sorted(
            {
                int(y)
                for y in scores[(scores["pair"] == pair) & (scores["scheme"] == "loyo")]["test_year"]
                if y != "all"
            }
        )
        rows = []
        for y in years:
            cells: list = [y]
            for method in METHODS:
                a = _row(scores, pair, "loyo", method, y, "block-month")
                b = _row(scores, pair, "loyo", method, y, "block-year")
                cells += [pct(a["bias"], True), pct(a["wape"]), pct(b["wape"])]
            cells.append(_lower(scores, pair, "loyo", "block-month", y))
            rows.append(cells)
        L += md_table(
            [
                "Year",
                "SA2.2 bias",
                "SA2.2 WAPE b-month",
                "SA2.2 WAPE b-year",
                "SA2.3 bias",
                "SA2.3 WAPE b-month",
                "SA2.3 WAPE b-year",
                "Lower error (b-month)",
            ],
            rows,
        )
        L.append("")
    L += ["Per-block detail (leave-one-year-out, test years pooled): `baselines_by_block.csv`.", ""]

    # --- k ---
    L += ["## Choice of k (SA2.2, leave-one-year-out)", ""]
    ks: dict[str, dict[int, str]] = {}
    for pair in MAIN_PAIRS:
        for f in inp.folds.get((pair, "loyo"), []):
            if f.method == "sf":
                ks.setdefault(pair, {})[f.test_year] = f"{f.k:g}" + (" (default)" if f.k_fallback else "")
    years = sorted({y for d in ks.values() for y in d})
    L += md_table(
        ["Test year"] + [DIRECTION[p] for p in MAIN_PAIRS],
        [[y] + [ks.get(p, {}).get(y, "-") for p in MAIN_PAIRS] for y in years],
    )
    L += [
        "",
        "`k` is a pseudo-count in source units: `k = 0` is the pure block ratio and `k = 10000` "
        "brings it almost to the national factor.",
        "",
    ]

    # --- Intervalos ---
    L += ["## Intervals", ""]
    L += [
        f"Nominal level {NOMINAL:.0%}. Empirical coverage over block-months (or block-years) with a source count greater "
        "than zero (what is known at prediction time), by test year (leave-one-year-out). `coverage_any` in the "
        "Reading section uses the earlier definition (source or observed > 0). Relative width = sum of widths / sum "
        "of predictions.",
        "",
        "- `jackknife (factor)` and `interannual dispersion` (inverse series only, block-month): factor +/- z * jackknife "
        "standard error (z = 1.28), and the 10 % and 90 % quantiles of the factors of each training year. "
        "They only describe the uncertainty of the factor, not the count noise of the test month.",
        "- `conformal (relative residuals)` (both directions, block-month and block-year): inside the training set "
        "of each outer split the inner leave-one-year-out is run (6-month gap, with the `k` already chosen "
        "for that split) and the out-of-sample relative residuals `obs / pred` are pooled over block-months "
        "with source > 0 (`obs = 0` gives residual 0). Predictions of up to "
        f"{SMALL_MONTH:g} hot spots (block-month) or {SMALL_YEAR:g} (block-year), 0 included, use an additive "
        "interval: conformal quantiles of `obs - pred` of those inner rows (threshold fixed in advance, not "
        f"tuned with any test year). The rest is stratified into 5 predicted-count classes, with edges at "
        f"quantiles of the out-of-sample training prediction (classes with fewer than {MIN_PER_BIN} "
        "residuals are merged with the neighbor). The interval is the class `pred * [q10, q90]`, with the "
        "finite-sample conformal correction (ranks ceil(0.9 (n+1)) and floor(0.1 (n+1))). Block-year does not sum "
        "block-month bounds: it is calibrated with residuals of block-year totals from the same inner years, with its "
        "own classes. Nothing is tuned with the outer test years. The inner models use one year less of "
        "training than the outer model, which tends to widen slightly.",
        "",
    ]
    cc_all = cov[cov["scheme"] == "loyo"]
    for pair in MAIN_PAIRS:
        for level in ("block-month", "block-year"):
            cc = cc_all[(cc_all["pair"] == pair) & (cc_all["level"] == level)]
            names = [n for n in INTERVALS if n in set(cc["interval"])]
            if not names:
                continue
            L += [f"### {DIRECTION[pair]}, {level}", ""]
            years = sorted({int(y) for y in cc["test_year"] if str(y) != "all"})
            rows = []
            for y in years + ["all"]:
                cells = ["all" if y == "all" else y]
                for name in names:
                    r = cc[(cc["interval"] == name) & (cc["test_year"].astype(str) == str(y))].iloc[0]
                    cells += [pct(r["coverage"]), num(r["rel_width"], 2)]
                rows.append(cells)
            L += md_table(
                ["Year"] + [f"{INTERVALS[n]} {h}" for n in names for h in ("coverage", "width")], rows
            )
            L.append("")
    L += ["### Conformal coverage by predicted size (leave-one-year-out, test years pooled)", ""]
    L += [
        "Fixed prediction classes (for information only, nothing is tuned with them); `n` = block-months (or "
        "block-years) with source > 0.",
        "",
    ]
    sz = coverage_by_size(folds)
    for pair in MAIN_PAIRS:
        for level in ("block-month", "block-year"):
            t = sz[(sz["pair"] == pair) & (sz["level"] == level)]
            if t.empty:
                continue
            L += [f"{DIRECTION[pair]}, {level}:", ""]
            rows = [
                [
                    "= 0"
                    if r["hi"] == 0
                    else f"({r['lo']:g}, {r['hi']:g}]"
                    if np.isfinite(r["hi"])
                    else f"> {r['lo']:g}",
                    int(r["n"]),
                    pct(r["coverage"]),
                    num(r["rel_width"], 2),
                ]
                for _, r in t.iterrows()
            ]
            L += md_table(["Prediction", "n", "Coverage", "Width"], rows)
            L.append("")
    L += ["### Reading", ""]
    conf = cc_all[(cc_all["interval"] == "conformal") & (cc_all["test_year"].astype(str) == "all")]
    inside = []
    for _, r in conf.iterrows():
        ok = 0.75 <= r["coverage"] <= 0.85
        inside.append(ok)
        L.append(
            f"- {DIRECTION[r['pair']]}, {r['level']}: coverage {pct(r['coverage'])} "
            f"({'inside' if ok else 'OUTSIDE'} 75-85 %), width {num(r['rel_width'], 2)}; with source or observed "
            f"> 0 (earlier definition): {pct(r['coverage_any'])}. Out of the factor's reach (source = 0 and "
            f"observed > 0): {int(r['n_out'])} rows, {pct(r['out_share'])} of the target detections; "
            "factor and interval predict 0 there."
        )
    L += [
        "",
        "All direction x level combinations fall within 75-85 %: "
        + ("yes." if all(inside) else "no (see those marked OUTSIDE)."),
        "",
        "Rows with source = 0 and observed > 0 are not covered by construction (the factor has nothing "
        "to multiply): the other sensor sees hot spots where this one marked none. Their count and their share of "
        "the detections are reported above and do not enter the headline coverage, which uses only rows defined "
        "by the source, known at prediction time. Coverage by year varies more at block-year (few rows per test "
        "year). Training residuals are treated as exchangeable with those of the test year: if the "
        "relationship changes over time (for example Terra drift, unverified), the coverage of a year "
        "may fall below.",
        "",
    ]

    # --- Variantes ---
    L += ["## Variants: Terra only and NOAA-20 -> S-NPP (leave-one-year-out)", ""]
    rows = []
    for pair in ("viirs_to_terra", "terra_to_viirs", "noaa20_to_snpp"):
        for method, mname in METHODS.items():
            a = _row(scores, pair, "loyo", method, "all", "block-month")
            b = _row(scores, pair, "loyo", method, "all", "block-year")
            if a is None:
                continue
            rows.append([PAIRS[pair].label, mname, pct(a["bias"], True), pct(a["wape"]), pct(b["wape"])])
    L += md_table(["Pair", "Method", "Bias b-month", "WAPE b-month", "WAPE b-year"], rows)
    L.append("")

    # --- Estabilidad ---
    L += ["## Stability", ""]
    L += [
        "National ratios of sums by year with the default count (0.1° grid). `Months` = complete months "
        "used (partial ones are excluded). No epoch adjustment: this is the table the design asks for "
        "to decide whether one is needed. The per-block table is not included in this run.",
        "",
        "### MODIS / S-NPP by year",
        "",
    ]
    rows = [
        [
            int(r["year"]),
            int(r["months"]),
            num(r["ratio"]),
            num(r["ratio_day"]),
            num(r["ratio_night"]),
            num(r["terra_snpp"]),
            num(r["aqua_snpp"]),
        ]
        for _, r in mod.iterrows()
    ]
    L += md_table(["Year", "Months", "MODIS/S-NPP", "Day", "Night", "Terra/S-NPP", "Aqua/S-NPP"], rows)
    L += ["", "### NOAA-20 / S-NPP by year (control without MODIS)", ""]
    n20 = inp.grid_tables["noaa20_snpp"]
    L += md_table(
        ["Year", "Months", "NOAA-20/S-NPP", "Day", "Night"],
        [
            [
                int(r["year"]),
                int(r["months"]),
                num(r["ratio"], 4),
                num(r["ratio_day"], 4),
                num(r["ratio_night"], 4),
            ]
            for _, r in n20.iterrows()
        ],
    )
    L += ["", "### Terra / Aqua by year", ""]
    ta = inp.grid_tables["terra_aqua"]
    L += md_table(
        ["Year", "Months", "Terra/Aqua", "Day", "Night"],
        [
            [int(r["year"]), int(r["months"]), num(r["ratio"]), num(r["ratio_day"]), num(r["ratio_night"])]
            for _, r in ta.iterrows()
        ],
    )
    L += ["", "### Mean acquisition time (UTC) by satellite and year", ""]
    L += [
        "Detections after the default filter, from `acq_datetime`. Night hours after "
        "12:00 are averaged as negative hours so as not to cut at midnight.",
        "",
    ]
    hrs = inp.det_tables["hours"]
    cols = [(s, dn) for s in ("terra", "aqua", "snpp", "noaa20") for dn in ("D", "N")]
    piv = hrs.pivot_table(index="year", columns=["satellite", "daynight"], values="hour")
    rows = []
    for y in piv.index:
        rows.append([int(y)] + [hhmm(piv.loc[y, c]) if c in piv.columns else "-" for c in cols])
    L += md_table(["Year"] + [f"{s} {dn}" for s, dn in cols], rows)
    L += ["", "### With and without the `type` filter", ""]
    L += [
        "MODIS/S-NPP ratio from the detections, with the default filter (`type` = 0) and without a `type` filter "
        "(`types=(0,1,2,3)`, with missing `type` included; same confidence filters). The partial month 2012-01 "
        "is excluded. Fraction with `type` other than 0 = 1 - filtered count / unfiltered count.",
        "",
    ]
    rows = []
    for _, r in types.iterrows():
        rows.append(
            [
                int(r["year"]),
                int(r["modis_def"]),
                int(r["modis_all"]),
                pct(r["modis_type_share"]),
                num(r["ratio_def"]),
                num(r["ratio_all"]),
                pct(r["snpp_type_share"]),
            ]
        )
    L += md_table(
        [
            "Year",
            "MODIS filtered",
            "MODIS unfiltered",
            "MODIS type != 0",
            "MODIS/S-NPP filtered",
            "MODIS/S-NPP unfiltered",
            "S-NPP type != 0",
        ],
        rows,
    )
    L.append("")

    if inp.ml is not None:
        from firecal.stages.harmonize.ml_report import ml_section

        L += ml_section(inp.ml, [f for f in folds if f.method in ("sf", "qm")], inp.ml_prev)

    L += ["## Notes", ""]
    L += [
        "- What causes each difference between years (MODIS version, source type, orbital drift) is "
        "**unverified**: the tables only describe.",
        "- The inverse series estimates how many hot spots VIIRS would have recorded in a block and month; it does not locate "
        "individual hot spots. It is called 'estimated', never 'detected'.",
        "- There is no epoch adjustment: if the stability table shows a step with the NOAA-20/S-NPP control "
        "flat, the design calls for an epoch adjustment and resuming SA2.8.",
    ]
    return "\n".join(L) + "\n"
